import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import axios from "axios";

const TakeQuiz = () => {
  const location = useLocation();
  const { state: formData } = location;

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [quizData, setQuizData] = useState(null);

  const prompt = `Generate a set of quiz questions having 4 choices and 1 correct answer based on the following data given in JSON format: 
  ${JSON.stringify(formData)} 
  Generate the questions in JSON format.`;

  const fetchQuiz = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await axios.post(
        "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=AIzaSyDzzLAYxe6PJiBrh_dL5B020aO6pIZx6NQ",
        {
          prompt: {
            text: prompt,
          },
        }
      );

      if (response.data?.candidates?.[0]?.content) {
        // Store the raw response text
        setQuizData(response.data.candidates[0].content);
      } else {
        throw new Error("Invalid response format from the API.");
      }
    } catch (err) {
      console.error("Error fetching quiz:", err);
      setError(err.message || "An error occurred while fetching the quiz.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (formData) {
      fetchQuiz();
    }
  }, [formData]);

  const parseQuizData = (data) => {
    try {
      if (!data) return null;

      // Convert string to JSON
      return JSON.parse(data.trim());
    } catch (err) {
      console.error("Failed to parse quiz data:", err);
      setError("Failed to parse quiz data. Please check the response format.");
      return null;
    }
  };

  const quiz = parseQuizData(quizData);

  return (
    <div className="container mx-auto p-4">
      {loading && <p className="text-center text-blue-600">Loading...</p>}
      {error && <p className="text-center text-red-600">{error}</p>}
      {quiz && (
        <div>
          <h3 className="text-xl font-semibold text-center mb-4">
            Quiz Questions
          </h3>
          <pre className="bg-gray-100 p-4 rounded-lg shadow-lg max-h-[400px] overflow-auto text-sm font-mono whitespace-pre-wrap break-words">
            {JSON.stringify(quiz, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
};

export default TakeQuiz;
